{{ config(materialized='table') }}
-- Self-referencing table(s): 'WI_AUD_RSTD_BKG_THRSHLD_VALUES' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
 'MT_RSTD_BKGS_MEASURE_ORDER_MTH' AS AUDIT_TABLE_NAME,
 'ALL_COLUMNS' AS AUDIT_COLUMN_NAME,
 CASE
  WHEN COUNT(*) >= 1
   THEN 'Y' ELSE 'N'
 END AS AMOUNTDIFF_FLG
  FROM
  (
  SELECT
   MTH.*,
   THR.AUDIT_COLUMN_NAME
   FROM
   {{ source('raw', 'WI_AUD_RSTD_BKG_THRSHLD_VALUES') }} THR
   INNER JOIN
    {{ source('raw', 'WI_AUD_RSTD_BKGS_MEASURE_MTH') }} MTH
   ON
   MTH.AUDIT_TABLE_NAME = THR.AUDIT_TABLE_NAME
   AND COLLATE(THR.AUDIT_TABLE_NAME, 'en-ci-rtrim') = 'MT_RSTD_BKGS_MEASURE_ORDER_MTH'
  WHERE
  (MTH.TRADE_IN_AMOUNT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_NET_PRICE_AMOUNT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_LIST_PRICE_AMOUNT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_COST_AMOUNT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_EXTENDED_QUANTITY NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_HOLD_NET_PRICE_AMT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_HOLD_LIST_PRICE_AMT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_HOLD_COST_AMOUNT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_EXTENDED_HOLD_QUANTITY NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE
  OR
  DD_COMP_US_STANDARD_PRICE_AMT NOT BETWEEN THR.MIN_THRESHOLD_VALUE AND THR.MAX_THRESHOLD_VALUE)
 )
 A